fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both vectors have the same length, we can iterate over them together
    // and compare each pair of elements for inequality.

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x != y)
        .collect()
}